import{_ as o,l,o as a,c as s,v as r,p,x as t,d as n,i as P,S as d}from"./chunks/framework.InCnrqk-.js";const A=JSON.parse('{"title":"XDP 与 eBPF 网络","description":"","frontmatter":{"title":"XDP 与 eBPF 网络","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/xdp-ebpf.md","filePath":"cs/xdp-ebpf.md","lastUpdated":1789023840000}'),c={name:"cs/xdp-ebpf.md"};function D(f,e,h,_,E,u){const i=l("Mermaid");return a(),s("div",null,[e[1]||(e[1]=r('<h1 id="xdp-与-ebpf-网络" tabindex="-1">XDP 与 eBPF 网络 <a class="header-anchor" href="#xdp-与-ebpf-网络" aria-label="Permalink to &quot;XDP 与 eBPF 网络&quot;">​</a></h1><div class="epigraph"><p>XDP 在驱动 DMA 之后、skb 分配之前运行 eBPF：可以丢包、改包、重定向，用更少的每包开销做数据面。</p><footer>—— 据 Linux XDP 文档；Høiland-Jørgensen 等对 XDP 的论述；eBPF 网络钩子说明</footer></div><p><a href="/cs/bridge-tun-tap">上一课</a>留下的缺口接到本课。 <a href="/cs/napi">NAPI</a> 建 skb 已经贵。<a href="/cs/netfilter-conntrack">netfilter</a> 更在 skb 之后。缺口是 <strong>XDP</strong>：可编程、早、可 JIT，对象仍是包，不是大模型推理。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>DDoS 小包：CPU 死在分配 skb。XDP 程序看以太网/IP/TCP 头，返回 DROP/PASS/TX/REDIRECT。PASS 才走普通 RX。缺口：verifier 保证程序终止与内存安全；map 做计数与黑名单；与 tc eBPF、socket filter 的挂钩点不同。本课不把 verifier 算法写成编译课。</p><p><span class="marginnote">generic XDP 在 skb 之后跑，方便无驱动支持，但失去早丢的意义。驱动 native/offload 才是本课动机。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>加载：<code>bpf(2)</code> 把程序挂到 <code>netdev</code>。poll 路径：<code>bpf_prog_run_xdp</code>。重定向到另一设备或 AF_XDP 套接字进用户态。对照 <a href="/cs/fuse">FUSE</a>：都是「内核把事件交给可编程体」，一个是文件，一个是包。对照 iptables：XDP 更早、无 conntrack 除非自己用 map 做。</p>',8)),(a(),p(d,null,{default:t(()=>[P(i,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DMA%5B%22DMA%20%E6%8F%8F%E8%BF%B0%E7%AC%A6%22%5D%20--%3E%20XDP%5B%22XDP%20eBPF%22%5D%0A%20%20XDP%20--%3E%7C%22DROP%22%7C%20GONE%5B%22%E4%B8%8D%E5%BB%BA%20skb%22%5D%0A%20%20XDP%20--%3E%7C%22PASS%22%7C%20SKB%5B%22%E8%B5%B0%20GRO%2F%E5%8D%8F%E8%AE%AE%E6%A0%88%22%5D%0A%20%20XDP%20--%3E%7C%22REDIRECT%22%7C%20DEV%5B%22%E5%85%B6%E5%AE%83%E8%AE%BE%E5%A4%87%E6%88%96%20AF_XDP%22%5D%0A"})]),fallback:t(()=>[...e[0]||(e[0]=[n(" Loading... ",-1)])]),_:1})),e[2]||(e[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>XDP 把数据面从固定 C 路径里打开一个可验证窗口，使过滤与转发能在每核百万 PPS 上活。它不替代 TCP 状态机。不要写成 AI 包分类。与 <a href="/cs/cgroups">cgroup</a>：程序可读 cgroup id，策略仍要人写。</p><p>安全：能挂 XDP 需要 CAP_NET_ADMIN 或 bpf 权限；错误程序被 verifier 拒。</p><p>实现上：AF_XDP 把 umem 注册给驱动，用户 poll 描述符，是 XDP 与 DPDK 之间的折中。verifier 禁循环（或限制迭代），复杂解析要拆 helper。offload 到网卡后调试面变窄。 读法上只引用<a href="/cs/bridge-tun-tap">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「网络栈 / 收发路径」课序里，对象是 <strong>XDP 与 eBPF 网络</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有 helper 列表。不保证网卡硬件 offload 与软件语义一致。下一课更彻底的旁路：DPDK 不经过内核协议栈。</p><p>版本字段会变，课序钉的是机制对象「XDP 与 eBPF 网络」，不是某一主线内核的结构体名。 后课默认：可在 skb 前用 eBPF 处理包。用户态驱动轮询网卡，下一课 DPDK。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>XDP 在建 skb 前跑 eBPF，可丢可转。</li><li>verifier 限制程序；map 保存状态。</li><li>内核旁路 DPDK 是下一课。</li><li>出处：Linux XDP；Høiland-Jørgensen et al.；eBPF 文档。</li></ul>',11))])}const B=o(c,[["render",D]]);export{A as __pageData,B as default};
